        "econnreset",
        "socket hang up",
        "fetch failed",
        "networkerror",
        "network error",
        "transport closed",
        "connection closed",
        "connection lost",
        "other side closed",
        "broken pipe",
        "epipe",
        "terminated",
        "write after end",
        "server unavailable",
